export default '/**\n * Stackra file contract:\n * Purpose: the "offer" demo of the native Countdown: a White Friday offer that ends in two days.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0302 (decisions 3 and 5);\n *          ADR 0060 (light, dark, RTL); STA-1371 (wave A, owner request 2026-10-29).\n */\nimport { Countdown, useCatalogueText } from "@stackra/ui/native";\nimport { View } from "react-native";\nimport { useState } from "react";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { COUNTDOWN_DEMO_KEYS } from "#src/demos/free/countdown/countdown-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = COUNTDOWN_DEMO_KEYS.demo_free.countdown.offer;\n\n/** Countdown: a White Friday offer that ends in two days. */\nexport default function Offer() {\n  const t = useCatalogueText(MESSAGES.en);\n  const [to] = useState(() => new Date(Date.now() + ((2 * 24 + 5) * 3600 + 42 * 60) * 1000));\n  return (\n    <View>\n      <Countdown label={t(K.label)} to={to} />\n    </View>\n  );\n}\n';
